import React from 'react';
import { graphql } from 'gatsby';
import { useTranslation } from 'gatsby-plugin-react-i18next';
import styled from 'styled-components';
import Layout from '../components/layout/Layout';
import WorkReachSketch from '../components/visualizations/WorkReachSketch';

const ProjectHero = styled.section`
  min-height: 60vh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: ${props => props.theme.space[20]} ${props => props.theme.space[6]};
  background: linear-gradient(
    135deg,
    var(--color-bg) 0%,
    var(--color-surface) 100%
  );
  position: relative;
  overflow: hidden;

  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: radial-gradient(
      circle at 20% 50%,
      rgba(255, 107, 53, 0.1) 0%,
      transparent 50%
    );
    pointer-events: none;
  }
`;

const HeroContent = styled.div`
  max-width: ${props => props.theme.containers.lg};
  margin: 0 auto;
  position: relative;
  z-index: 1;
`;

const ProjectCategory = styled.span`
  display: inline-block;
  font-size: ${props => props.theme.typography.fontSizes.sm};
  font-weight: ${props => props.theme.typography.fontWeights.semibold};
  color: ${props => props.theme.colors.primary};
  text-transform: uppercase;
  letter-spacing: ${props => props.theme.typography.letterSpacings.wider};
  margin-bottom: ${props => props.theme.space[4]};
`;

const ProjectTitle = styled.h1`
  font-size: ${props => props.theme.typography.fontSizes['6xl']};
  margin-bottom: ${props => props.theme.space[6]};
  background: linear-gradient(
    135deg,
    ${props => props.theme.colors.primary} 0%,
    ${props => props.theme.colors.accent} 100%
  );
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;

  @media (max-width: ${props => props.theme.breakpoints.md}) {
    font-size: ${props => props.theme.typography.fontSizes['4xl']};
  }
`;

const ProjectDescription = styled.p`
  font-size: ${props => props.theme.typography.fontSizes['2xl']};
  color: var(--color-text-secondary);
  max-width: 800px;
  line-height: ${props => props.theme.typography.lineHeights.relaxed};
`;

const ProjectContent = styled.article`
  max-width: ${props => props.theme.containers.lg};
  margin: 0 auto;
  padding: ${props => props.theme.space[12]} ${props => props.theme.space[6]};

  h2 {
    font-size: ${props => props.theme.typography.fontSizes['4xl']};
    margin-top: ${props => props.theme.space[16]};
    margin-bottom: ${props => props.theme.space[6]};
    color: var(--color-text);
  }

  h3 {
    font-size: ${props => props.theme.typography.fontSizes['2xl']};
    margin-top: ${props => props.theme.space[10]};
    margin-bottom: ${props => props.theme.space[4]};
    color: var(--color-text);
  }

  p {
    font-size: ${props => props.theme.typography.fontSizes.lg};
    line-height: ${props => props.theme.typography.lineHeights.relaxed};
    margin-bottom: ${props => props.theme.space[6]};
  }

  img {
    width: 100%;
    border-radius: ${props => props.theme.radii.xl};
    margin: ${props => props.theme.space[8]} 0;
    box-shadow: ${props => props.theme.shadows.xl};
  }

  ul, ol {
    font-size: ${props => props.theme.typography.fontSizes.lg};
    line-height: ${props => props.theme.typography.lineHeights.relaxed};
    margin-bottom: ${props => props.theme.space[6]};
  }

  li {
    margin-bottom: ${props => props.theme.space[3]};
  }

  blockquote {
    border-left: 4px solid ${props => props.theme.colors.primary};
    padding-left: ${props => props.theme.space[6]};
    margin: ${props => props.theme.space[8]} 0;
    font-style: italic;
    color: var(--color-text-secondary);
  }

  code {
    background-color: var(--color-surface);
    padding: ${props => props.theme.space[1]} ${props => props.theme.space[2]};
    border-radius: ${props => props.theme.radii.sm};
    font-family: ${props => props.theme.typography.fonts.mono};
    font-size: 0.9em;
  }

  pre {
    background-color: var(--color-surface);
    padding: ${props => props.theme.space[6]};
    border-radius: ${props => props.theme.radii.lg};
    overflow-x: auto;
    margin: ${props => props.theme.space[8]} 0;

    code {
      background: none;
      padding: 0;
    }
  }

  hr {
    margin: ${props => props.theme.space[12]} 0;
    border: none;
    height: 1px;
    background: linear-gradient(
      90deg,
      transparent 0%,
      var(--color-border) 50%,
      transparent 100%
    );
  }
`;

function ProjectDetail({ data }) {
  const { markdownRemark: project } = data;
  const { t } = useTranslation();

  if (!project) {
    return <div>Project not found</div>;
  }

  const { frontmatter, html } = project;
  const isWorkReach = frontmatter.page_id === 'workreach';

  return (
    <Layout
      title={frontmatter.title}
      description={frontmatter.description}
      image={frontmatter.img}
      path={`/projects/${frontmatter.page_id}`}
    >
      <ProjectHero>
        <HeroContent>
          <ProjectCategory>
            {t(`projects.category.${frontmatter.category}`, frontmatter.category)}
          </ProjectCategory>
          <ProjectTitle>{frontmatter.title}</ProjectTitle>
          {frontmatter.description && (
            <ProjectDescription>{frontmatter.description}</ProjectDescription>
          )}
        </HeroContent>
      </ProjectHero>

      <ProjectContent>
        {/* For WorkReach project, show the interactive visualization */}
        {isWorkReach && <WorkReachSketch />}

        {/* Render the markdown content */}
        <div dangerouslySetInnerHTML={{ __html: html }} />
      </ProjectContent>
    </Layout>
  );
}

export default ProjectDetail;

export const query = graphql`
  query ProjectByIdAndLanguage($id: String!, $language: String!) {
    markdownRemark(id: { eq: $id }) {
      id
      html
      frontmatter {
        page_id
        title
        description
        img
        category
        importance
        related_publications
        lang
      }
    }
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
